  systemInstruction += `4. ⚠️ ATURAN FORMATTING WHATSAPP WAJIB (MANDATORY):\n`;
  systemInstruction += `   - Balasan DITAMPILKAN PADA APLIKASI WHATSAPP.\n`;
  systemInstruction += `   - WAJIB gunakan WhatsApp Markdown (*teks tebal*, _teks miring_, bullet •, dan monospace \`kode\`).\n`;
  systemInstruction += `   - DILARANG KERAS menggunakan tag HTML seperti <b>, <br>, <i>, <p>, <div> karena WhatsApp TIDAK MERENDER HTML! Gunakan baris baru (\\n) untuk jeda baris.\n`;
  systemInstruction += `5. KHUSUS LAPORAN KENDALA DARI EKSEKUTIF (report_customer_issue):\n`;
  systemInstruction += `   - Tetapkan urgensi 'darurat' / 'tinggi' (VIP Escalation) agar segera menjadi atensi prioritas engineering di Jira.\n\n`;
