const templateKeys = Object.keys(rawTemplates);

systemInstruction += `\n📚 PANDUAN KNOWLEDGE BASE DARI CMS (KASUS & SOLUSI RESMI PROJECT MANAGEMENT):\n`;
systemInstruction += `Jika pertanyaan atau keluhan pengguna cocok atau mirip dengan kasus di bawah ini, WAJIB utamakan memberikan panduan solusi terstruktur berikut:\n\n`;

if (templateKeys.length > 0) {
  templateKeys.forEach((key, idx) => {
    const tpl = rawTemplates[key];
    const topic = tpl.topic || key;
    const keywords = Array.isArray(tpl.keywords) ? tpl.keywords.join(', ') : '';
    const steps = Array.isArray(tpl.steps) ? tpl.steps.join('\n  ') : (tpl.raw_solution || '');
    const escalation = tpl.escalation || '';

    systemInstruction += `${idx + 1}. KASUS: "${topic}"\n`;
    systemInstruction += `- Intent Identifikasi: 'troubleshoot_${key}'\n`;
    if (keywords) {
      systemInstruction += `- Kata Kunci / Pertanyaan Terkait: ${keywords}\n`;
    }
    systemInstruction += `- Solusi yang Disampaikan ke Pengguna:\n  ${steps}\n`;
    if (escalation) {
      systemInstruction += `- Panduan Eskalasi: ${escalation}\n`;
    }
    systemInstruction += `\n`;
  });
}

systemInstruction += `📋 DAFTAR ACTION / KAPABILITAS SISTEM YANG TERSEDIA:\n`;
systemInstruction += JSON.stringify(safeCapabilities, null, 2) + `\n\n`;
systemInstruction += `DAFTAR INTENT PERCAKAPAN STANDAR:\n`;
systemInstruction += `- greeting: Salam / sapaan pembuka kedinasan (selamat pagi/siang, assalamu'alaikum, halo, dsb.)\n`;
systemInstruction += `- check_spp_status: Mengecek status pencairan SPP atau konfirmasi transaksi non-tunai\n`;
systemInstruction += `- check_realisasi_apbdes: Menanyakan realisasi anggaran belanja dan pendapatan APBDes\n`;
systemInstruction += `- check_saldo_kas_desa: Menanyakan saldo kas desa atau rekening kas di Bank BPD\n`;
systemInstruction += `- check_status_pajak_billing: Menanyakan status potongan pajak atau ID Billing DJP\n`;
systemInstruction += `- export_laporan_tnt_excel: Meminta file rekapitulasi laporan transaksi dalam bentuk spreadsheet Excel (.xlsx / .csv)\n`;
systemInstruction += `- report_customer_issue: Melaporkan masalah/kendala sistem, akun terkunci, atau bug penatausahaan\n`;
systemInstruction += `- ask_help: Menanyakan apa yang bisa dibantu atau fitur penatausahaan yang tersedia\n`;
systemInstruction += `- chitchat: Percakapan sopan, terima kasih, ucapan penutup\n`;
systemInstruction += `- request_clarification: Jika maksud pengguna kurang jelas atau butuh informasi nomor SPP/kwitansi tambahan\n`;
systemInstruction += `- fallback_unknown: Jika di luar konteks sistem aplikasi\n\n`;
systemInstruction += `FORMAT OUTPUT WAJIB (HANYA JSON VALID, TANPA BACKTICK DI LUAR JSON):\n`;
systemInstruction += `{\n`;
systemInstruction += `  \"intent\": \"<nama_action_atau_intent_standar>\",\n`;
systemInstruction += `  \"confidence\": <skor_0_sampai_1>,\n`;
systemInstruction += `  \"parameters\": {\n`;
systemInstruction += `    \"<key>\": \"<value>\"\n`;
systemInstruction += `  },\n`;
systemInstruction += `  \"requires_action\": <true_jika_perlu_eksekusi_action_lainnya_false>,\n`;
systemInstruction += `  \"matched_action\": \"<nama_action_terpilih_atau_null>\",\n`;
systemInstruction += `  \"context_note\": \"<catatan singkat pemahaman konteks dari memory jika multi-turn>\",\n`;
systemInstruction += `  \"reply\": \"<tanggapan sesuai channel: WhatsApp Markdown jika WhatsApp, HTML jika Web. WAJIB SAPA DENGAN BAPAK/IBU, DILARANG SIKAP KAK/KAKAK!>\"\n`;
systemInstruction += `}`; 

const contents = [];

historyMessages.forEach(msg => {
  contents.push({
    role: msg.role === 'assistant' ? 'model' : 'user',
    parts: [{ text: sanitizePII(msg.message) }]
  });
});

contents.push({
  role: 'user',
  parts: [{ text: inputData.message }]
});

// 🔑 Gemini API Key Pool & Rotasi Otomatis
const rawEnvKeys = ($env.GEMINI_API_KEYS || $env.GEMINI_API_KEY || "").trim();
const geminiKeys = rawEnvKeys
  .split(/[,;\s\n\r]+/)
  .map(k => k.trim())
  .filter(k => k.length > 8 && k !== "your_gemini_api_key_here");

let chosenKey = "";
let keyIndex = 0;

if (geminiKeys.length > 0) {
  const seedStr = (inputData.conversation_id || "") + "-" + Date.now() + "-" + Math.random();
  let hash = 0;
  for (let i = 0; i < seedStr.length; i++) {
    hash = ((hash << 5) - hash) + seedStr.charCodeAt(i);
    hash |= 0;
  }
  keyIndex = Math.abs(hash) % geminiKeys.length;
  chosenKey = geminiKeys[keyIndex];
} else {
  chosenKey = $env.GEMINI_API_KEY || "";
}

return [{
  json: {
    conversation_id: inputData.conversation_id,
    user_id: inputData.user_id,
    user_name: inputData.user_name,
    message: inputData.message,
    raw_message_has_pii: inputData.raw_message_has_pii,
    screenshot: inputData.screenshot || null,
    screenshot_name: inputData.screenshot_name || null,
    channel: inputData.channel,
    role: inputData.role || (inputData.channel === 'whatsapp' ? 'executive' : 'customer'),
    backend_base_url: inputData.backend_base_url,
    internal_api_key: inputData.internal_api_key,
    slack_webhook_url: inputData.slack_webhook_url,
    slack_channel: inputData.slack_channel,
    telegram_bot_token: inputData.telegram_bot_token,
    telegram_chat_id: inputData.telegram_chat_id,
    whatsapp_api_url: inputData.whatsapp_api_url,
    whatsapp_api_key: inputData.whatsapp_api_key,
    whatsapp_target_number: inputData.whatsapp_target_number,
    default_endpoints: rawEndpoints,
    gemini_api_key: chosenKey,
    key_pool: geminiKeys,
    key_index: keyIndex,
    payload: {
      systemInstruction: {
        parts: [{ text: systemInstruction }]
      },
      contents: contents,
      generationConfig: {
        temperature: 0.2,
        maxOutputTokens: 2048,
        responseMimeType: 'application/json',
        thinkingConfig: {
          thinkingBudget: 0
        }
      }
    }
  }
}];

const geminiResp = $input.first().json;
const promptData = $('Build Gemini Prompt').item.json;
const manifestResp = ($('Fetch AI Manifest') && $('Fetch AI Manifest').item && $('Fetch AI Manifest').item.json) || {};
const keyPool = Array.isArray(promptData.key_pool) ? promptData.key_pool : [];
let usedKeyIndex = promptData.key_index || 0;
let failoverSuccess = false;

const isExecutive = promptData.channel === 'whatsapp' || (promptData.role && promptData.role.includes('executive'));

// 🔄 Auto-Failover: Jika key terkena 429
if (geminiResp && geminiResp.error && keyPool.length > 1) {
  const isRateLimited = geminiResp.error.code === 429 ||
                        (geminiResp.error.message && /quota|exhausted|rate limit/i.test(geminiResp.error.message)) ||
                        geminiResp.error.status === "RESOURCE_EXHAUSTED";

  if (isRateLimited) {
    for (let i = 1; i < keyPool.length; i++) {
      const backupIndex = (usedKeyIndex + i) % keyPool.length;
      const backupKey = keyPool[backupIndex];
      try {
        const retryUrl = "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=" + backupKey;
        const retryRes = await fetch(retryUrl, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(promptData.payload)
        });
        const retryJson = await retryRes.json();
        if (retryJson && !retryJson.error && retryJson.candidates && retryJson.candidates.length > 0) {
          geminiResp = retryJson;
          usedKeyIndex = backupIndex;
          failoverSuccess = true;
          break;
        }
      } catch (err) {}
    }
  }
}

const endpoints = Array.isArray(manifestResp.endpoints) && manifestResp.endpoints.length > 0
  ? manifestResp.endpoints
  : (promptData.default_endpoints || []);

function extractJson(text) {
  if (!text) return null;
  const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
